    16  /** @file
    17   * @brief Fuzzer program for local IJ and related functions (gridDistance,
    18   * gridPathCells)
    19   */
    20
    21  #include "aflHarness.h"
    22  #include "h3api.h"
    23  #include "utility.h"
    24
    25  typedef struct {
    26      H3Index index;
    27      H3Index index2;
    28      int i;
    29      int j;
    30      uint32_t mode;
    31  } inputArgs;
    32
    33  void testTwoIndexes(H3Index index, H3Index index2) {
    34      int64_t distance;
    35      H3_EXPORT(gridDistance)(index, index2, &distance);
    36      int64_t size;
    37      H3Error err = H3_EXPORT(gridPathCellsSize)(index, index2, &size);
    38      if (!err) {
    39          H3Index *output = calloc(size, sizeof(H3Index));
    40          H3_EXPORT(gridPathCells)(index, index2, output);
    41          free(output);
    42      }
    43  }
    44
    45  int LLVMFuzzerTestOneInput(const uint8_t *data, size_t size) {
    46      if (size < sizeof(inputArgs)) {
    47          return 0;
    48      }
    49      const inputArgs *args = (const inputArgs *)data;
    50
    51      // Note that index and index2 need to be in the approximate area for these
    52      // tests to make sense.
    53      // Test with mode set to 0 since that is expected to yield more interesting
    54      // results.
    55      testTwoIndexes(args->index, args->index2);
    56      H3Index out;
    57      CoordIJ ij = {.i = args->i, .j = args->j};
    58      H3Error err = H3_EXPORT(localIjToCell)(args->index, &ij, 0, &out);
    59      if (!err) {
    60          testTwoIndexes(args->index, out);
    61      }
    62
    63      H3_EXPORT(cellToLocalIj)(args->index, args->index2, 0, &ij);
    64
    65      // Test again with mode
    66      uint32_t mode = args->mode;
    67      err = H3_EXPORT(localIjToCell)(args->index, &ij, mode, &out);
    68      if (!err) {
    69          testTwoIndexes(args->index, out);
    70      }
    71
    72      H3_EXPORT(cellToLocalIj)(args->index, args->index2, mode, &ij);
    73
    74      return 0;
    75  }
    76
    77  AFL_HARNESS_MAIN(sizeof(inputArgs));
